// Heap Sort step-by-step generator
export function generateSteps(input) {
  const arr = [...input];
  const steps = [];
  const n = arr.length;
  let comparisons = 0;
  let swaps = 0;

  // Helper to add a step
  const addStep = (type, i, j, msg) => {
    steps.push({
      type,
      indices: [i, j],
      arr: [...arr],
      comparisons,
      swaps,
      msg,
    });
  };

  // Heapify helper
  const heapify = (size, root) => {
    let largest = root;
    const left = 2 * root + 1;
    const right = 2 * root + 2;

    // Compare left child
    if (left < size) {
      comparisons++;
      addStep('compare', root, left, `Compare arr[${root}]=${arr[root]} with arr[${left}]=${arr[left]}`);
      if (arr[left] > arr[largest]) {
        largest = left;
      }
    }

    // Compare right child
    if (right < size) {
      comparisons++;
      addStep('compare', root, right, `Compare arr[${root}]=${arr[root]} with arr[${right}]=${arr[right]}`);
      if (arr[right] > arr[largest]) {
        largest = right;
      }
    }

    // Swap if needed
    if (largest !== root) {
      swaps++;
      [arr[root], arr[largest]] = [arr[largest], arr[root]];
      addStep('swap', root, largest, `Swap arr[${root}] and arr[${largest}]`);
      heapify(size, largest);
    }
  };

  // Build max heap
  addStep('message', -1, -1, 'Phase 1: Building max heap...');
  for (let i = Math.floor(n / 2) - 1; i >= 0; i--) {
    addStep('message', i, -1, `Heapifying from index ${i}`);
    heapify(n, i);
  }

  // Extract elements from heap
  addStep('message', -1, -1, 'Phase 2: Extracting sorted elements...');
  for (let i = n - 1; i > 0; i--) {
    swaps++;
    [arr[0], arr[i]] = [arr[i], arr[0]];
    addStep('swap', 0, i, `Move max to position ${i}`);

    addStep('message', -1, -1, `Heapifying reduced heap (size=${i})`);
    heapify(i, 0);
  }

  addStep('done', -1, -1, `Sorted! Comparisons: ${comparisons}, Swaps: ${swaps}`);

  return steps;
}
